mapper.select:
SELECT * FROM (
    SELECT ROWNUM AS rn, t.* FROM (
        SELECT i.insured_id, i.customer_id, c.name AS customer_name,
               i.name, i.birth_date, i.gender, i.phone, i.relation, i.reg_date
        FROM insured_person i
        JOIN customer c ON i.customer_id = c.customer_id

            ORDER BY i.name ASC
            ORDER BY i.reg_date ASC
            ORDER BY i.reg_date DESC

    ) t WHERE ROWNUM <= #{offset} + #{size}
) WHERE rn > #{offset}

SELECT * FROM (
    SELECT ROWNUM AS rn, t.* FROM (
        SELECT i.insured_id, i.customer_id, c.name AS customer_name,
               i.name, i.birth_date, i.gender, i.phone, i.relation, i.reg_date
        FROM insured_person i
        JOIN customer c ON i.customer_id = c.customer_id
        WHERE i.name LIKE '%' || #{keyword} || '%'
           OR c.name LIKE '%' || #{keyword} || '%'
           OR i.phone LIKE '%' || #{keyword} || '%'
        ORDER BY i.reg_date DESC
    ) t WHERE ROWNUM <= #{offset} + #{size}
) WHERE rn > #{offset}
